class ApronDairyFarmerFace extends StatelessWidget {
  final ApronDairyFarmerFaceExpression expression;
  final double? width;
  final double? height;
  final ColorMapper? colorMapper;

  const ApronDairyFarmerFace({
    required this.expression,
    this.width,
    this.height,
    this.colorMapper,
    super.key,
  });

  @override
  Widget build(BuildContext context) {
    late String svgString;
    switch (expression) {
      case ApronDairyFarmerFaceExpression.surprised:
        svgString = _dairyFarmerFaceSurprised;
      case ApronDairyFarmerFaceExpression.worry:
        svgString = _dairyFarmerFaceWorry;
      case ApronDairyFarmerFaceExpression.smile:
        svgString = _dairyFarmerFaceSmile;
    }
    return SvgPicture.string(
      svgString,
      height: height,
      width: width,
      colorMapper: colorMapper,
    );
  }
}
